from collections import deque


def avoid_count(n: int, alphabet: str, banned: list[str]) -> int:
    MOD = 1_000_000_007
    if n == 0:
        return 1

    k = len(alphabet)
    char_to_idx = {ch: i for i, ch in enumerate(alphabet)}

    next_node = [[-1] * k]
    fail = [0]
    bad = [False]

    for s in banned:
        u = 0
        for ch in s:
            c = char_to_idx[ch]
            if next_node[u][c] == -1:
                next_node[u][c] = len(next_node)
                next_node.append([-1] * k)
                fail.append(0)
                bad.append(False)
            u = next_node[u][c]
        bad[u] = True

    q = deque()
    for c in range(k):
        v = next_node[0][c]
        if v != -1:
            fail[v] = 0
            q.append(v)
        else:
            next_node[0][c] = 0

    while q:
        u = q.popleft()
        if bad[fail[u]]:
            bad[u] = True
        for c in range(k):
            v = next_node[u][c]
            if v != -1:
                fail[v] = next_node[fail[u]][c]
                q.append(v)
            else:
                next_node[u][c] = next_node[fail[u]][c]

    if bad[0]:
        return 0

    good_states = [i for i, is_bad in enumerate(bad) if not is_bad]
    state_to_idx = {s: i for i, s in enumerate(good_states)}
    m = len(good_states)

    mat = [[0] * m for _ in range(m)]
    for i, u in enumerate(good_states):
        for c in range(k):
            v = next_node[u][c]
            if not bad[v]:
                mat[i][state_to_idx[v]] += 1

    vec = [0] * m
    vec[0] = 1

    while n > 0:
        if n & 1:
            new_vec = [0] * m
            for i in range(m):
                vi = vec[i]
                if vi:
                    row = mat[i]
                    for j in range(m):
                        new_vec[j] += vi * row[j]
            vec = [x % MOD for x in new_vec]

        n >>= 1
        if n > 0:
            new_mat = [[0] * m for _ in range(m)]
            for i in range(m):
                row_i = mat[i]
                res_row = new_mat[i]
                for p in range(m):
                    aip = row_i[p]
                    if aip:
                        row_p = mat[p]
                        for j in range(m):
                            res_row[j] += aip * row_p[j]
                for j in range(m):
                    res_row[j] %= MOD
            mat = new_mat

    return sum(vec) % MOD
